sys_script.script:
(function createRetentionOnOnboard(current, previous) {
    // Make sure this matches your exact Retention Case table name
    var retCaseTable = 'x_2023506_german_1_ret_case'; 
    var chkinTable   = 'x_2023506_german_1_ret_chkin';

    // 1. Create Parent Retention Case
    var retCase = new GlideRecord(retCaseTable);
    retCase.initialize();
    retCase.setValue('u_imm_case', current.getUniqueValue());
    retCase.setValue('u_candidate_name', current.getValue('u_candidate_name'));
    retCase.setValue('u_candidate_email', current.getValue('u_candidate_email'));
    retCase.setValue('u_retention_status', 'active');

    var today = new GlideDate();
    retCase.setValue('u_arrival_date', today.getValue());

    var retCaseId = retCase.insert();

    if (!retCaseId) {
        gs.error('Failed to create Retention Case for: ' + current.getValue('number'));
        return;
    }

    // 2. Create the 4 Milestones
    var milestones = [
        { milestone: '30_days', days: 30 },
        { milestone: '60_days', days: 60 },
        { milestone: '90_days', days: 90 },
        { milestone: '150_days', days: 150 }
    ];

    for (var i = 0; i < milestones.length; i++) {
        var checkin = new GlideRecord(chkinTable);
        checkin.initialize();
        checkin.setValue('u_retention_case', retCaseId);
        checkin.setValue('u_milestone', milestones[i].milestone);
        checkin.setValue('u_status', 'scheduled');
        checkin.setValue('u_needs_intervention', false);

        var due = new GlideDateTime();
        due.addDaysLocalTime(milestones[i].days);
        checkin.setValue('u_due_date', due.getLocalDate().getValue());

        checkin.insert();
    }

    // NOTE: Do NOT call current.update() here!
    gs.addInfoMessage('Retention Case and 4 check-in milestones successfully generated.');
})(current, previous);
